  "eras": [
    {
      "id": "era-mine",
      "name": "銅山の時代",
      "begins": -40,
      "ends": 0
    },
    {
      "id": "era-after",
      "name": "閉山後",
      "begins": 1,
      "ends": 15
    }
  ],
  "events": [
    {
      "id": "ev-1",
      "year": -40,
      "title": "銅山の開坑",
      "cause": "",
      "effect": "山のふもとに飯場と郵便局ができた。",
      "trace": "坑口の門柱と、開坑式の記念写真。",
      "era": "era-mine"
    },
    {
      "id": "ev-2",
      "year": -18,
      "title": "東坑の出水",
      "cause": "ev-1",
      "effect": "坑道の東側が閉じられ、水抜きの作業が続いた。",
      "trace": "水没した東坑の水抜き跡と、当時の作業日誌。",
      "era": "era-mine"
    },
    {
      "id": "ev-3",
      "year": 0,
      "title": "閉山と坑道の閉鎖",
      "cause": "ev-2",
      "effect": "人口が半分になり、町の記録は閉山の年で閉じられた。",
      "trace": "掲示板に残る閉山の告示。閉山の日に坑道へ入った者がいるという言い伝えも、告示の脇に鉛筆で書かれている。",
      "era": "era-mine"
    },
    {
      "id": "ev-4",
      "year": 1,
      "title": "銅山記念会の結成",
      "cause": "ev-3",
      "effect": "年寄りたちが年一度、坑道の点検を続けることになった。",
      "trace": "記念会の名簿と、点検のたびに書かれた一枚の記録。",
      "era": "era-after"
    },
    {
      "id": "ev-5",
      "year": 15,
      "title": "郵便局の保管棚の整理",
      "cause": "ev-4",
      "effect": "三年を過ぎた保管物の中から、宛名のない三通の手紙が出てきた。",
      "trace": "整理のときに付けた荷札と、棚の奥に残った消印のない封筒。",
      "era": "era-after"
    }
  ],
  "sources": [
